/// <summary>
/// Extension class for InventLocation form data source to handle MCRPickingWBWarehouseInfo.
/// </summary>
[ExtensionOf(formDataSourceStr(InventLocation, MCRPickingWBWarehouseInfo))]
final class METInventLocationFormMCRWhsDS_Extension
{
}

Method.Source:
/// <summary>
/// Validate the record before writing.
/// Added for Bug 303414: When warehouse save failed - a record in MCRPickingWBWarehouseInfo remains
/// </summary>
/// <returns></returns>
public boolean validateWrite()
{
    boolean                         ret;
    InventLocation                  inventLocation;
    MCRPickingWBWarehouseInfo       mcrInfo;

    inventLocation = this.cursor();

    // If the InventLocation record has no RecId (not persisted), remove any
    // existing MCRPickingWBWarehouseInfo rows that reference the same
    // InventLocationId.
    if (inventLocation.RecId == 0 && inventLocation.InventLocationId)
    {
        ttsBegin;
        delete_from mcrInfo
            where mcrInfo.Warehouse == inventLocation.InventLocationId;
        ttsCommit;
    }

    ret = next validateWrite();
    return ret;
}
